cd /tmp/main-edit && python3 - <<'EOF'
import re,glob
bad=[]; n=0
for f in sorted(glob.glob('S*/E*.md')):
    t=open(f).read(); n+=1
    m=re.match(r'^---\ntitle: "(.*)"\nsummary: "(.*)"\nseason: \d+\nepisode: \d+\nstatus: (?:ongoing|complete)\n---\n\n(.*?)\n\n\*\*', t, re.S)
    if not m: bad.append((f,'frontmatter')); continue
    if m.group(2)!=m.group(3): bad.append((f,'summary paragraph mismatch'))
    srcs=re.findall(r'^Source: friend/(\w+) @ ([0-9a-f]{40})$', t, re.M)
    if len(srcs)!=len(set(s for _,s in srcs)): bad.append((f,'duplicate source'))
    if not m.group(1).startswith("The One With"): bad.append((f,'title style'))
print("files:",n,"problems:",bad)
EOF
